def transform(grid):
    h, w = len(grid), len(grid[0])

    # The first full-width separator follows the top row of n-by-n templates.
    sep = next(
        r for r, row in enumerate(grid)
        if r > 0 and sum(v == 5 for v in row) >= 2 * (sum(v == 5 for v in grid[0]))
    )
    n = sep
    starts = list(range(0, w - n + 1, n + 1))

    templates = []
    for s in starts:
        block = [row[s:s+n] for row in grid[:n]]
        colors = [v for row in block for v in row if v not in (0, 5)]
        if colors:
            color = max(set(colors), key=colors.count)
            templates.append((s, color, block))

    marker_row = max(
        r for r in range(h)
        if any(v not in (0, 5) for v in grid[r])
    )
    recolor = {}
    for s, color, _ in templates:
        c = s + n // 2
        marker = grid[marker_row][c]
        if marker not in (0, 5):
            recolor[color] = marker

    out = [[0] * (n * n) for _ in range(n * n)]
    # Each panel below the divider is a layer of the n-by-n tile arrangement.
    for s in starts:
        for r in range(n):
            for c in range(n):
                source = grid[sep + 1 + r][s + c]
                if source not in recolor:
                    continue
                tile = next(block for _, color, block in templates if color == source)
                marker = recolor[source]
                for dr in range(n):
                    for dc in range(n):
                        if tile[dr][dc] == source:
                            out[r*n + dr][c*n + dc] = marker
                        elif tile[dr][dc] == 0:
                            out[r*n + dr][c*n + dc] = 0
    return out
